insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"dermaquest","slug":"3d-stem-cell-eye-cream","title_zh_hk":"3D\u5e79\u7d30\u80de\u773c\u971c","title_zh_cn":"3D\u5e72\u7ec6\u80de\u773c\u971c","title_en":"3D Stem Cell Eye Cream","description_zh_hk":"<p>\u9069\u5408\u6240\u6709\u808c\u819a</p>\n<p>\u6700\u65b0\u7814\u767c\u7684\u6d77\u6d0b\u751f\u7269\u79d1\u6280\uff0c\u914d\u5408\u9ad8\u7d14\u5ea6\u6894\u5b50\u82b1\u53ca\u6d77\u6ab3\u523a\u82b9\u5e79\u7d30\u80de\u3001\u91ab\u5b78\u86cb\u767d\u80bd\u53ca\u5176\u4ed6\u6709\u6548\u6210\u4efd\uff0c\u76f4\u63a5\u89e3\u6c7a\u773c\u888b\u53ca\u773c\u76ae\u4e0b\u5782\u7b49\u554f\u984c\u3002\u5168\u9762\u6536\u7dca\u773c\u90e8\u76ae\u819a\uff0c\u63d0\u5347\u8f2a\u5ed3\u30023D\u5e79\u7d30\u80de\u773c\u971c\u540c\u6642\u6e1b\u6de1\u9ed1\u773c\u5708\u53ca\u773c\u7d0b\uff0c\u4ee4\u96d9\u773c\u56de\u5fa9\u660e\u4eae\u5149\u5f69\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u5f37\u6548\u91ab\u5b78\u5e79\u7d30\u80de\u914d\u65b9\u6539\u5584\u773c\u7d0b\u53ca\u773c\u888b\u554f\u984c</p>\n<p>\u2013 \u542b\u8c50\u5bcc\u6297\u6c27\u5316\u7269</p>\n<p>\u2013 \u63d0\u4f9b\u4fdd\u6fd5\u529f\u80fd\uff0c\u63d0\u5347\u53ca\u7e2e\u7dca\u773c\u90e8\u808c\u819a</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u6d77\u6ff1\u523a\u82b9\u5e79\u7d30\u80de</p>\n<p>\u2013 \u6894\u5b50\u82b1\u5e79\u7d30\u80de</p>\n<p>\u2013 \u6d77\u8334\u9999\u5e79\u7d30\u80de</p>","description_zh_cn":"<p>\u9002\u5408\u6240\u6709\u808c\u80a4</p>\n<p>\u6700\u65b0\u7814\u53d1\u7684\u6d77\u6d0b\u751f\u7269\u79d1\u6280\uff0c\u914d\u5408\u9ad8\u7eaf\u5ea6\u6800\u5b50\u82b1\u53ca\u6d77\u69df\u523a\u82b9\u5e72\u7ec6\u80de\u3001\u533b\u5b66\u86cb\u767d\u80bd\u53ca\u5176\u4ed6\u6709\u6548\u6210\u4efd\uff0c\u76f4\u63a5\u89e3\u51b3\u773c\u888b\u53ca\u773c\u76ae\u4e0b\u5782\u7b49\u95ee\u9898\u3002\u5168\u9762\u6536\u7d27\u773c\u90e8\u76ae\u80a4\uff0c\u63d0\u5347\u8f6e\u5ed3\u30023D\u5e72\u7ec6\u80de\u773c\u971c\u540c\u65f6\u51cf\u6de1\u9ed1\u773c\u5708\u53ca\u773c\u7eb9\uff0c\u4ee4\u53cc\u773c\u56de\u590d\u660e\u4eae\u5149\u5f69\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u5f3a\u6548\u533b\u5b66\u5e72\u7ec6\u80de\u914d\u65b9\u6539\u5584\u773c\u7eb9\u53ca\u773c\u888b\u95ee\u9898</p>\n<p>\u2013 \u542b\u4e30\u5bcc\u6297\u6c27\u5316\u7269</p>\n<p>\u2013 \u63d0\u4f9b\u4fdd\u6e7f\u529f\u80fd\uff0c\u63d0\u5347\u53ca\u7f29\u7d27\u773c\u90e8\u808c\u80a4</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u6d77\u6ee8\u523a\u82b9\u5e72\u7ec6\u80de</p>\n<p>\u2013 \u6800\u5b50\u82b1\u5e72\u7ec6\u80de</p>\n<p>\u2013 \u6d77\u8334\u9999\u5e72\u7ec6\u80de</p>","description_en":"<p>Suitable for all skin types</p>\n<p>Marine biotechnology with gardenia and sea holly stem cells, peptides and actives to target eye bags, sagging lids, dark circles and fine lines.</p>\n<p>Key benefits</p>\n<p>\u2013 Medical stem-cell formula for wrinkles and puffiness</p>\n<p>\u2013 Rich in antioxidants</p>\n<p>\u2013 Hydrates, lifts and firms the eye contour</p>\n<p>Key ingredients</p>\n<p>\u2013 Sea holly stem cells</p>\n<p>\u2013 Gardenia stem cells</p>\n<p>\u2013 Sea fennel stem cells</p>","price_hkd":890,"stock":20,"image_paths":["/images/products/prod-2@2x.jpg"],"sort":228}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;